import{_ as o,o as t,c as a,ai as c}from"./chunks/framework.Cg3BiOJh.js";const u=JSON.parse('{"title":"Viable Prompt Protocol v1.5","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md","lastUpdated":1786775408000}'),l={name:"spec/index.md"};function d(i,e,n,r,s,p){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="viable-prompt-protocol-v1-5" tabindex="-1">Viable Prompt Protocol v1.5 <a class="header-anchor" href="#viable-prompt-protocol-v1-5" aria-label="Permalink to &quot;Viable Prompt Protocol v1.5&quot;">​</a></h1><p>Manifest digest: <code>3f8948a2838ddc33</code></p><p>VPP is a tagged, closed-loop conversation protocol. The user places one command on line 1; the assistant returns exactly one allowed wrapper tag, a body, and the canonical footer.</p><h2 id="grammar" tabindex="-1">Grammar <a class="header-anchor" href="#grammar" aria-label="Permalink to &quot;Grammar&quot;">​</a></h2><p><code>!&lt;tag&gt; [--modifier ...]</code></p><ul><li>Parse line 1 only. Later lines are content, even when they contain bang tags.</li><li>Tags and modifiers are case-sensitive.</li><li>User tags: <code>!&lt;g&gt;</code>, <code>!&lt;q&gt;</code>, <code>!&lt;o&gt;</code>, <code>!&lt;c&gt;</code>, <code>!&lt;o_f&gt;</code>, <code>!&lt;e&gt;</code>, <code>!&lt;e_o&gt;</code>.</li><li>Assistant tags: <code>&lt;g&gt;</code>, <code>&lt;q&gt;</code>, <code>&lt;o&gt;</code>, <code>&lt;c&gt;</code>, <code>&lt;o_f&gt;</code>.</li><li>Correctness modifiers: <code>--correct</code>, <code>--incorrect</code>.</li><li>Severity modifiers: <code>--minor</code>, <code>--major</code>.</li><li>Duplicate or contradictory modifiers are invalid.</li><li>Pipeline destinations must be one of <code>--&lt;g&gt;</code>, <code>--&lt;q&gt;</code>, <code>--&lt;o&gt;</code>, <code>--&lt;c&gt;</code>, <code>--&lt;o_f&gt;</code>.</li></ul><h2 id="transitions" tabindex="-1">Transitions <a class="header-anchor" href="#transitions" aria-label="Permalink to &quot;Transitions&quot;">​</a></h2><ul><li>Valid ordinary commands mirror their tag.</li><li><code>!&lt;e&gt; --&lt;tag&gt;</code> starts a new locus at cycle 1 and routes to <code>&lt;tag&gt;</code>.</li><li><code>!&lt;e_o&gt;</code> starts an immediate output pipeline at <code>&lt;o&gt;</code> and cycle 1.</li><li><code>!&lt;o&gt; --correct --&lt;tag&gt;</code> starts an explicit pipeline at cycle 1.</li><li><code>!&lt;o&gt; --incorrect</code> and <code>!&lt;o_f&gt; --incorrect</code> route to <code>&lt;c&gt;</code>.</li><li>Invalid commands deterministically route to <code>&lt;c&gt;</code> with a recovery body.</li></ul><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><p>The default locus is <code>default</code>. Cycle starts at 1. Every valid user <code>!&lt;c&gt;</code> advances the cycle, capped at 3. New-locus escapes, immediate-output escapes, explicit pipelines, and a new command after <code>&lt;o_f&gt;</code> reset cycle to 1.</p><p>Tag indexes are conversation-global. They continue across cycle resets and locus changes, and reset only when the caller begins a new conversation with no prior state. Unnamed locus jumps are assigned <code>locus-2</code>, <code>locus-3</code>, and so on.</p><p>At cycle 3 the formatter adds the canonical escape choices when the body does not already contain both forms:</p><blockquote><p>Escape options: send <code>!&lt;e&gt; --&lt;g&gt;</code> (or <code>--&lt;q&gt;</code>, <code>--&lt;o&gt;</code>, <code>--&lt;c&gt;</code>, <code>--&lt;o_f&gt;</code>) to change locus, or <code>!&lt;e_o&gt;</code> to start an output pipeline.</p></blockquote><h2 id="content-contracts" tabindex="-1">Content contracts <a class="header-anchor" href="#content-contracts" aria-label="Permalink to &quot;Content contracts&quot;">​</a></h2><ul><li><code>&lt;g&gt;</code>: Stay conceptual. Snippets are allowed; do not emit full files or modules.</li><li><code>&lt;q&gt;</code>: Ask broad, uncertainty-reducing questions or provide diagnostic framing.</li><li><code>&lt;o&gt;</code>: Produce a realized deliverable and include assumptions, citations, and tests when relevant.</li><li><code>&lt;c&gt;</code>: Critique or clarify at fine context, targeting concrete deltas and asking no more than 25 questions.</li><li><code>&lt;o_f&gt;</code>: Produce the publishable final result with a brief rationale and acceptance checklist.</li></ul><p>The runtime enforces structure: commands, wrappers, modifiers, counters, cycles, loci, footer fields, and wrapper placement. Meaning-level obligations such as concept-only behavior and citation quality remain model or evaluation concerns.</p><h2 id="footer" tabindex="-1">Footer <a class="header-anchor" href="#footer" aria-label="Permalink to &quot;Footer&quot;">​</a></h2><p><code>[Version=v1.5 | Tag=&lt;tag&gt;_&lt;index&gt; | Sources=&lt;none|web&gt; | Assumptions=&lt;n&gt; | Cycle=&lt;i&gt;/3 | Locus=&lt;name&gt;]</code></p><p><code>Sources</code> is <code>none</code> or <code>web</code>. <code>Assumptions</code> is a caller-declared non-negative integer. No text may appear outside the header, body, and footer.</p>',19)])])}const m=o(l,[["render",d]]);export{u as __pageData,m as default};
